void Solver::bump_var(int var, double coeff) {
    // Apply the bump using the current increment factor.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy rescaling to avoid overflow: if any activity becomes too large,
    // scale down all activities and the increment factor at once.
    const double MAX_ACT = 1e150;
    if (activity[var] > MAX_ACT) {
        const double SCALE = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap consistent.
    // If the variable is already in the heap, update its position;
    // otherwise insert it so that newly bumped variables can be selected promptly.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
